export const docGroups = ['Get started', 'Core concepts', 'Guides', 'SDKs', 'API reference', 'Resources'];
const guideOrder = ['guides/authentication', 'guides/builder', 'guides/subscriptions', 'guides/customers-invoices', 'guides/provider-gas', 'guides/agent-spending', 'guides/x402', 'guides/mcp', 'guides/avalanche'];
docs.sort((a, b) => docGroups.indexOf(a.group) - docGroups.indexOf(b.group) ||
  (a.group === 'Guides' ? guideOrder.indexOf(a.slug) - guideOrder.indexOf(b.slug) : 0));
export function getDoc(slug: string) { return docs.find(page => page.slug === slug); }
export const docsNavigation = docs.map(({ slug, group, title, description, sections }) => ({ slug, group, title, description, sections: sections.map(({ id, title }) => ({ id, title })) }));
